fn _pe_chalk_hash12(p: vec2f) -> f32 {
    var p3 = fract(vec3f(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

fn _pe_chalk_hash22(p: vec2f) -> vec2f {
    var p3 = fract(vec3f(p.xyx) * vec3f(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

fn _pe_chalk_noise2d(p: vec2f) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);

    let n00 = _pe_chalk_hash12(i + vec2f(0.0, 0.0));
    let n10 = _pe_chalk_hash12(i + vec2f(1.0, 0.0));
    let n01 = _pe_chalk_hash12(i + vec2f(0.0, 1.0));
    let n11 = _pe_chalk_hash12(i + vec2f(1.0, 1.0));

    return mix(mix(n00, n10, u.x), mix(n01, n11, u.x), u.y);
}

fn _pe_chalk_fbm(p: vec2f) -> f32 {
    var total = 0.0;
    var amp = 0.50;
    var freq = 1.0;
    var pos = p;
    for (var i = 0u; i < 4u; i++) {
        total += amp * _pe_chalk_noise2d(pos * freq);
        freq *= 2.13;
        amp *= 0.48;
        pos = vec2f(pos.x * 0.866 - pos.y * 0.5, pos.x * 0.5 + pos.y * 0.866);
    }
    return total;
}

fn _pe_chalk_worley(p: vec2f) -> vec2f {
    let i = floor(p);
    let f = fract(p);
    var min_dist = 1.0;
    var rand_id = 0.0;
    for (var y = -1; y <= 1; y++) {
        for (var x = -1; x <= 1; x++) {
            let neighbor = vec2f(f32(x), f32(y));
            let h = _pe_chalk_hash22(i + neighbor);
            let pt = neighbor + 0.15 + 0.70 * h;
            let d = length(pt - f);
            if (d < min_dist) {
                min_dist = d;
                rand_id = h.x;
            }
        }
    }
    return vec2f(min_dist, rand_id);
}
